-- Demande d'Ève du 07.11.2026 : un e-mail marqué comme spam par le serveur ne s'affiche pas.
-- Depuis ce jour il n'entre plus (looksSpam, server/lib/mailbox/types.ts). Pour ceux encore « à trier » :
--   - une entrée de la file (message_id « triage:… ») n'est qu'une copie de l'expéditeur, de l'objet et de la date, le
--     message reste dans la boîte de la personne. Elle est effacée, comme la purge à 30 jours l'aurait fait ;
--   - un e-mail reçu par l'adresse de capture porte son texte : il passe à « écarté », sans être effacé.
-- Même règle que looksSpam, contrôlée par scripts/smoke.ts. Rejouable.
delete from email_messages
 where status = 'new' and direction = 'in' and project_id is null and message_id like 'triage:%'
   and (subject ~* '^\s*(\[[^]]{1,40}\]\s*)*(\[\s*\**\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\**\s*\]|\(\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\)|\{\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\}|<\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*>|\*+\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\*+)'
        or subject ~ '^\s*SPAM(:|\s\|\s|\s-\s)');
update email_messages set status = 'ignored'
 where status = 'new' and direction = 'in'
   and (subject ~* '^\s*(\[[^]]{1,40}\]\s*)*(\[\s*\**\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\**\s*\]|\(\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\)|\{\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\}|<\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*>|\*+\s*((possible|probable|probably|potential|suspected|suspect|likely|maybe|verdacht\s+auf)[-\s]+)?(spam|spamverdacht|pourriel|(courrier\s+)?ind[ée]sirables?|junk|(posta\s+)?indesiderata|(correo\s+)?no\s+deseado)\y\s*\??\s*([-:=]?\s*(score\s*[:=]?\s*)?\d{1,2}([.,]\d+)?(/\d+)?|-\s*(low|medium|high))?\s*\*+)'
        or subject ~ '^\s*SPAM(:|\s\|\s|\s-\s)');
